import React, { useState, useEffect } from "react";
import {
  saveDayStatus,
  getTodayKey,
  getAllDays,
} from "../utils/dailyStatus";

const SpiritualRoutineCard = () => {
  const todayKey = getTodayKey();
  const allDays = getAllDays();

  const [routine, setRoutine] = useState(
    allDays[todayKey] || {
      jap: false,
      reading: false,
      prayer: false,
    }
  );

  useEffect(() => {
    saveDayStatus(routine);
  }, [routine]);

  const handleChange = (field) => {
    setRoutine({ ...routine, [field]: !routine[field] });
  };

  return (
    <div style={card}>
      <h3>🧘 Spiritual Routine</h3>

      <label>
        <input
          type="checkbox"
          checked={routine.jap}
          onChange={() => handleChange("jap")}
        />
        Jap Done
      </label>
      <br />

      <label>
        <input
          type="checkbox"
          checked={routine.reading}
          onChange={() => handleChange("reading")}
        />
        Reading Done
      </label>
      <br />

      <label>
        <input
          type="checkbox"
          checked={routine.prayer}
          onChange={() => handleChange("prayer")}
        />
        Prayer Done
      </label>
    </div>
  );
};
